<?php
declare(strict_types=1);
namespace App\Application\QuestionLearning\Service;
use App\Domain\QuestionLearning\Enum\LearningEventType;use App\Domain\QuestionLearning\Enum\LearningOutcome;use App\Domain\QuestionLearning\Repository\LearningEventRepositoryInterface;use App\Domain\QuestionLearning\ValueObject\LearningSignalAggregate;
final readonly class GetLearningSignalAggregateService { public function __construct(private LearningEventRepositoryInterface $events) {} public function execute(string $userId,string $taxonomySubjectId,\DateTimeImmutable $since): LearningSignalAggregate { $items=$this->events->listForUserSubject($userId,$taxonomySubjectId,$since);$answers=0;$correct=0;$incorrect=0;$enabled=0;$disabled=0;$last=null;foreach($items as $event){$last=$event->occurredAt;if($event->type===LearningEventType::ANSWER_COMPLETED){$answers++;if($event->outcome===LearningOutcome::CORRECT)$correct++;if($event->outcome===LearningOutcome::INCORRECT)$incorrect++;}if($event->type===LearningEventType::NOT_MASTERED_ENABLED)$enabled++;if($event->type===LearningEventType::NOT_MASTERED_DISABLED)$disabled++;}return new LearningSignalAggregate($userId,$taxonomySubjectId,$answers,$correct,$incorrect,$enabled,$disabled,$last); } }
